CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE tenants (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL REFERENCES tenants(id), email TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE birth_profiles (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL, user_id UUID NOT NULL, birth_date DATE NOT NULL, birth_time TIME, timezone TEXT NOT NULL, latitude NUMERIC NOT NULL, longitude NUMERIC NOT NULL, house_system TEXT DEFAULT 'whole_sign', zodiac_mode TEXT DEFAULT 'tropical', metadata JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE life_events (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL, owner_user_id UUID NOT NULL, event_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ, timezone TEXT NOT NULL, location_id UUID, emotional_valence NUMERIC, emotional_intensity NUMERIC, importance_score NUMERIC DEFAULT 0, source_type TEXT NOT NULL, source_ref TEXT, confidence NUMERIC DEFAULT 1.0, metadata JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), deleted_at TIMESTAMPTZ);
CREATE TABLE planetary_positions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL, profile_id UUID, chart_context TEXT NOT NULL, body TEXT NOT NULL, timestamp TIMESTAMPTZ NOT NULL, zodiac_longitude NUMERIC NOT NULL, sign TEXT NOT NULL, degree_in_sign NUMERIC NOT NULL, house INTEGER, speed NUMERIC, retrograde BOOLEAN, declination NUMERIC, right_ascension NUMERIC, engine_version TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE derived_points (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL, source_point_id UUID, source_pair JSONB, point_type TEXT NOT NULL, zodiac_longitude NUMERIC NOT NULL, sign TEXT NOT NULL, degree_in_sign NUMERIC NOT NULL, calculation_method TEXT NOT NULL, metadata JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE aspects (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL, point_a_id UUID NOT NULL, point_b_id UUID NOT NULL, aspect_type TEXT NOT NULL, exact_angle NUMERIC NOT NULL, actual_angle NUMERIC NOT NULL, orb NUMERIC NOT NULL, applying BOOLEAN, exact_at TIMESTAMPTZ, weight NUMERIC DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE agent_findings (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL, finding_type TEXT NOT NULL, claim TEXT NOT NULL, confidence NUMERIC NOT NULL, evidence JSONB NOT NULL, limitations JSONB DEFAULT '[]'::jsonb, created_by TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE forecast_objects (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL, theme TEXT NOT NULL, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, score_type TEXT NOT NULL, score NUMERIC NOT NULL, drivers JSONB DEFAULT '[]'::jsonb, evidence JSONB DEFAULT '[]'::jsonb, limitations JSONB DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ DEFAULT NOW());
